def verdict(fair: float | None, mcx_price: float | None, threshold: float, now_ist: datetime) -> dict[str, Any]:
    if fair is None:
        return {"state": "NO_MODEL", "title": "Model unavailable",
                "detail": "COMEX, the rupee or the MCX baseline is missing: see the data notes below."}
    opened = now_ist.time() >= datetime.strptime("09:00", "%H:%M").time() and now_ist.weekday() < 5
    if mcx_price is None:
        if opened:
            return {"state": "NEED_PRICE", "title": "Enter the MCX price",
                    "detail": f"MCX is open. Enter the current GOLD price (or connect ICICI) to compare with fair ₹{fair:,.0f}."}
        return {"state": "AWAITING_OPEN", "title": "Waiting for the open",
                "detail": f"Trade the open only if MCX opens within ₹{threshold:,.0f} of ₹{fair:,.0f}."}
    diff = mcx_price - fair
    if abs(diff) <= threshold:
        return {"state": "OK", "title": "OK to trade the open", "diff": round(diff, 0),
                "detail": f"MCX ₹{mcx_price:,.0f} is ₹{abs(diff):,.0f} {'above' if diff > 0 else 'below'} fair: the overnight move is priced in."}

