def _breeze_call(fn, *args, retries: int = 1, **kwargs):
    """Call a Breeze SDK method, retrying once on a transient network error."""
    import time as _t
    for attempt in range(retries + 1):
        try:
            return fn(*args, **kwargs)
        except Exception:
            if attempt == retries:
                raise
            _t.sleep(1.0)


