def _raw(panel: dict, field: str, day: pd.Timestamp, sym: str) -> float:
    """Real (unadjusted) price as NSE printed it that day."""
    try:
        adj = panel[field].at[day, sym]
        factor = panel["close"].at[day, sym] / panel["raw_close"].at[day, sym]
