def chunks(text: str, limit: int = 3900) -> list[str]:
    """Telegram caps a message at 4,096 characters: split on line breaks."""
    out, cur = [], ""
    for line in text.split("\n"):
        if len(cur) + len(line) + 1 > limit and cur:
            out.append(cur)
            cur = ""
        cur += line + "\n"
    if cur.strip():
        out.append(cur)
    return out


