def compute_atr(df: pd.DataFrame, window: int = 14) -> pd.Series:
    """Average True Range."""
    tr = np.maximum(
        df['high'] - df['low'],
        np.maximum(
            abs(df['high'] - df['close'].shift(1)),
            abs(df['low'] - df['close'].shift(1))
        )
    )
    atr = tr.rolling(window=window, min_periods=1).mean()
    return atr

