def movers_line(contrib: dict[str, Any]) -> str:
    """'- Who moved NIFTY (points): TCS +31 · INFY +31 · ICICIBANK +30 · drag KOTAKBANK −7 (explains +357 of +359)'."""
    ms = [m for m in contrib.get("members") or [] if m.get("points") is not None]
    if len(ms) < 5:
