    up = [m for m in ms if m["points"] > 0][:3]
    dn = [m for m in reversed(ms) if m["points"] < 0][:2]
    txt = " · ".join(f"{m['symbol']} {m['points']:+.0f}" for m in up)
    if dn:
        txt += " · drag " + " · ".join(f"{m['symbol']} {m['points']:+.0f}" for m in dn)
    if contrib.get("change") is not None:
